// HYBRID retrieval: fuse a semantic arm and a keyword arm, then ground the LLM on the result.
//
// Why two arms: dense/semantic search is great at meaning but bad at exact tokens - BGE turns
// 'INV-2024-0891' into a nearly meaningless vector, so no amount of cosine will find it. Keyword
// search is the opposite: literal on IDs, blind to paraphrase. Neither alone is enough for a
// document pipeline where users ask both 'what were the taxes?' and 'show me invoice INV-2024-0891'.
//
// Fusion is Reciprocal Rank Fusion (RRF): score = sum over arms of 1/(k + rank). It is RANK-based,
// so it needs no score calibration between two arms whose numbers are not comparable (cosine vs
// term-count). A chunk ranked high in EITHER arm surfaces; one ranked high in BOTH wins.
const cfg = $('Config').first().json;
const query = String(cfg.query || '');
const minScore = cfg.minScore != null ? Number(cfg.minScore) : 0.45;
const topK = cfg.topK != null ? Number(cfg.topK) : 8;
const RRF_K = 60;  // standard damping constant; keeps any single arm from dominating

// --- ARM A: dense. Qdrant returns these ranked by cosine; cut the weak tail (it always returns
// topK however irrelevant, so without this an unrelated doc gets cited as a source).
const denseAll = ((($('Qdrant Search').first().json) || {}).result || []).filter(h => h && h.payload && h.payload.text);
const dense = denseAll.filter(h => Number(h.score) >= minScore);

// --- ARM B: keyword. Rank by how many distinct query terms the chunk literally contains.
const STOP = new Set(['the','and','for','was','were','are','what','which','who','how','many','much','its','this','that','there','their','have','has','had','from','with','about','any','all','get','tell','show','give','does','did','can','could','would','should','you','your','our','not','but','into','over','under','than','then','when','where','why','been','being','they','them']);
const terms = [...new Set((query.toLowerCase().match(/[a-z0-9][a-z0-9._\/-]{2,}/g) || []))].filter(t => !STOP.has(t));
const kwPoints = (((($json) || {}).result) || {}).points || [];  // [] if the keyword arm degraded
const keyword = kwPoints
  .filter(p => p && p.payload && p.payload.text)
  .map(p => { const low = String(p.payload.text).toLowerCase();
              return { id: p.id, payload: p.payload, score: null, matched: terms.filter(t => low.includes(t)).length }; })
  .filter(p => p.matched > 0)
  .sort((a, b) => b.matched - a.matched);

// --- FUSE ---
const fused = new Map();
function fuse(list, arm) {
  list.forEach((h, i) => {
    const id = String(h.id);
    const e = fused.get(id) || { id: h.id, payload: h.payload, score: null, matched: 0, arms: [], rrf: 0 };
    e.rrf += 1 / (RRF_K + i + 1);
    e.arms.push(arm);
    if (h.score != null) e.score = Math.round(Number(h.score) * 1000) / 1000;
    if (h.matched) e.matched = h.matched;
    fused.set(id, e);
  });
}
fuse(dense, 'dense');
fuse(keyword, 'keyword');

const ranked = [...fused.values()].sort((a, b) => b.rrf - a.rrf).slice(0, topK);
const sources = [...new Set(ranked.map(e => e.payload.source_file).filter(Boolean))];
const context = ranked.map(e => '[' + (e.payload.source_file || 'doc') + ']\n' + e.payload.text).join('\n\n---\n\n');
const userPrompt = 'Context:\n' + context + '\n\nQuestion: ' + query;
// 'matches' is the audit trail: which chunk, its cosine, how many terms hit, and which arm found it.
const matches = ranked.map(e => ({ file: e.payload.source_file, score: e.score, terms: e.matched, via: [...new Set(e.arms)].join('+'), rrf: Math.round(e.rrf * 10000) / 10000 }));
// denseTop/retrieved describe what was REJECTED, so the no-match path can distinguish 'the store is
// empty' from 'chunks came back but all scored too low' (which usually means minScore is too high).
const denseTop = denseAll.length ? Math.round(Math.max(...denseAll.map(h => Number(h.score))) * 1000) / 1000 : 0;
return [{ json: { query, context, userPrompt, sources, matches, minScore, retrieved: denseAll.length, denseTop, denseKept: dense.length, keywordHits: keyword.length, hasHits: ranked.length > 0, hitCount: ranked.length } }];

// Shape the final response: the LLM's answer text + the source files it drew from.
// The Chat Completion custom node returns { content } (already <think>-stripped); fall back to the
// raw OpenAI choices shape in case returnFull was ever turned on. Strip <think> defensively either way.
let text = String($json.content != null ? $json.content : (((($json.choices || [])[0] || {}).message || {}).content || ''));
const close = text.lastIndexOf('</think>');
if (close !== -1) text = text.slice(close + 8);
text = text.replace(/<\/?think>/gi, '').trim();
if (!text) text = 'The model returned no answer (its reasoning block used the whole token budget). Try a shorter question or raise max_tokens.';
const bc = $('Build Context').first().json;
// 'matches' shows every retrieved chunk with its score and whether it passed minScore - so a wrong
// answer can always be traced to what was actually fed to the model.
return [{ json: { answer: text, sources: bc.sources, matches: bc.matches } }];

// Neither arm produced anything - answer honestly instead of hallucinating.
// Distinguish 'the store is empty' from 'chunks came back but all scored too low', because the
// second case usually means minScore is set too high for this corpus, not that the answer is absent.
const bc = $('Build Context').first().json;
const retrieved = bc.retrieved || 0;
const answer = retrieved
  ? 'I do not have that information in the stored documents. (' + retrieved + ' chunks were retrieved but none passed the relevance threshold of ' + bc.minScore + ' - the closest scored ' + bc.denseTop + ' - and no keyword matched either. If you expected a match, lower minScore in the Config node.)'
  : 'No documents are stored yet, or the collection is empty. Process a document through the pipeline first.';
return [{ json: { answer, sources: [], matches: bc.matches || [] } }];
